async function copyRange(){const rows=selectedRowIndexes(),cols=selectedColIndexes(),dataset=state.model.dataset;const text=rows.map(row=>cols.map(col=>dataset.rows[row]?.[col]??'').join('\t')).join('\n');state.clipboard=text;try{await navigator.clipboard.writeText(text);}catch{};$('#cs-save-status').textContent='Range copied';}
async function pasteRange(){let value=state.clipboard||'';try{value=await navigator.clipboard.readText()||value;}catch{};if(!value)return;const parsed=updateChartData(normalizeChartModel({chart_type:'Line Chart',dataset:{fields:[],rows:[]}}),value).dataset;const rows=selectedRowIndexes(),cols=selectedColIndexes();commit('Paste range',model=>{const next=normalizeChartModel(model);parsed.rows.forEach((row,rowOffset)=>row.forEach((cell,colOffset)=>{const targetRow=rows[0]+rowOffset,targetCol=cols[0]+colOffset;if(next.dataset.rows[targetRow]&&targetCol<next.dataset.fields.length)next.dataset.rows[targetRow][targetCol]=cell;}));next.dataset.revision+=1;return next;});}
function saveReport(){if(state.pending)return;const report=clone(state.reportModel);const items=Array.isArray(report.items)?report.items:[];const index=items.findIndex(item=>String(item?.id)===String(state.entry.id));if(index<0){$('#cs-save-status').textContent='Save failed: chart not found';return;}const entry=chartToEntry(items[index],state.model);items[index]=entry;report.items=items;const datasets=Array.isArray(report.datasets)?report.datasets:[];const datasetIndex=datasets.findIndex(dataset=>String(dataset?.id)===String(state.model.dataset_id));if(datasetIndex>=0)datasets[datasetIndex]=clone(state.model.dataset);else datasets.push(clone(state.model.dataset));report.datasets=datasets;const commitId=uid('chart-commit');state.pending=commitId;$('#cs-save-status').textContent='Saving…';root.dispatchEvent(new CustomEvent('visualizer_bridge',{bubbles:true,detail:JSON.stringify({bridge_version:1,type:'report.commit',payload:{report_id:boot.report_id,base_revision:state.revision,commit_id:commitId,model:report}})}));}
function back(){location.assign(`/visualizer?report=${encodeURIComponent(boot.report_id||'')}`);}
function onPathChange(node){const path=node.dataset.path;const value=node.type==='checkbox'?node.checked:parseControl(node.value,node.type==='number'?'number':'text');commit(`Change ${path}`,model=>{const next=normalizeChartModel(model);setPath(next,path,value);return next;});}
function addSeries(){const field=fields().find(item=>!state.model.series.some(series=>series.field===item.id));if(!field)return;commit('Add series',model=>{const next=normalizeChartModel(model);next.series=[...(next.series||[]),{id:uid('series'),field:field.id,label:field.name,axis:'primary',color:'#1769d1',visible:true,legend:true,markers:true}];return next;});}
function moveSeries(index,delta){commit('Reorder series',model=>{const next=normalizeChartModel(model),series=[...(next.series||[])],to=index+delta;if(to<0||to>=series.length)return next;[series[index],series[to]]=[series[to],series[index]];next.series=series;return next;});}
function applyRecommendation(index,previewOnly=false){const recommendation=state.model.recommendations?.[index];if(!recommendation)return;const candidate=normalizeChartModel({...switchChartType(state.model,recommendation.type),mapping:{...state.model.mapping,...(recommendation.mapping||{})},why:recommendation.reason||''},recommendation.type);if(previewOnly){state.recommendationPreview=candidate;render();return;}state.recommendationPreview=null;commit(`Apply ${recommendation.type} recommendation`,model=>{const next=switchChartType(model,recommendation.type);next.mapping={...next.mapping,...(recommendation.mapping||{})};next.recommendations=recommendationsFor(next);next.why=recommendation.reason||'';return next;});}
function handleChartClick(event){const target=event?.target;const legend=target?.closest?.('[data-legend-series]');if(legend&&state.model.legend.interactive&&state.model.interaction.legendFilter!==false){const name=legend.dataset.legendSeries,key=legend.dataset.seriesKey;commit('Toggle legend series',model=>{const next=normalizeChartModel(model);next.series=next.series.map(series=>String(series.key??series.name??series.label??'')===String(key)||series.label===name||series.name===name?{...series,visible:series.visible===false}:series);return next;});return;}const point=target?.closest?.('[data-chart-point],[data-wafer-die]');if(point){const index=Number(point.dataset.chartPoint??point.dataset.waferDie);if(Number.isInteger(index)){state.selectedRows=new Set([index]);state.selectedCols=new Set(selectionColumnsForMark(point));render();}}}
function handleAction(action){
  if(action==='back')return back();
  if(action==='undo')return undo();
  if(action==='redo')return redo();
  if(action==='save')return saveReport();
  if(action==='save-recipe')return saveRecipeToLibrary();
  if(action==='copy-setup'){state.clipboard=JSON.stringify(copyChartSetup(state.model));$('#cs-save-status').textContent='Chart setup copied';return;}
  if(action==='toggle-markers')return commit('Toggle point markers',model=>{const next=normalizeChartModel(model);next.visual.markers=!next.visual.markers;return next;});
  if(action==='toggle-theme'){state.dark=!state.dark;document.documentElement.setAttribute('data-theme',state.dark?'dark':'light');render();return;}
  if(action==='preview'){state.preview=true;render();return;}
  if(action==='preview-close'){state.preview=false;render();return;}
  if(action==='fit'){const wrap=$('#cs-canvas-wrap');if(wrap){state.previewWidth=Math.max(320,Math.min(1100,wrap.clientWidth-48));render();requestAnimationFrame(()=>wrap.scrollTo({top:0,left:0,behavior:'smooth'}));}return;}
  if(action==='export-json')return download(JSON.stringify({schema:'visembler.chart.document',version:1,report_id:boot.report_id,element_id:state.entry.id,chart:state.model},null,2),`${clean(state.model.chart_type).replaceAll(' ','_')}.json`,'application/json');
  if(action==='export-svg')return download(renderChartSvg(state.model,{width:1100,height:state.model.chart_type==='Wafer Map'?620:560,dark:state.dark}),`${clean(state.model.chart_type).replaceAll(' ','_')}.svg`,'image/svg+xml');
  if(action==='import-json')return $('#cs-import-json')?.click();
  if(action==='paste-data'){const value=$('#cs-paste-input')?.value||'';if(value)commit('Paste and profile data',model=>updateChartData(model,value));return;}
  if(action==='clear-data')return commit('Clear chart data',model=>updateChartData(model,''));
  if(action==='add-row')return commit('Add row',model=>addRow(model));
  if(action==='insert-row-above')return commit('Insert row above',model=>insertRow(model,Math.min(...selectedRowIndexes())));
  if(action==='insert-row-below')return commit('Insert row below',model=>insertRow(model,Math.max(...selectedRowIndexes())+1));
  if(action==='delete-rows')return commit('Delete selected rows',model=>deleteRows(model,selectedRowIndexes()));
  if(action==='add-column')return commit('Add column',model=>addColumn(model));
  if(action==='insert-col-left')return commit('Insert column left',model=>insertColumn(model,Math.min(...selectedColIndexes())));
  if(action==='insert-col-right')return commit('Insert column right',model=>insertColumn(model,Math.max(...selectedColIndexes())+1));
  if(action==='delete-cols')return commit('Delete selected columns',model=>deleteColumns(model,selectedColIndexes()));
  if(action==='copy-range')return copyRange();
  if(action==='paste-range')return pasteRange();
  if(action==='apply-transform')return addTransform();
  if(action==='clear-transforms'){state.transformDraft=null;state.transformEditIndex=null;return commit('Clear transforms',model=>{const next=normalizeChartModel(model);next.transforms={steps:[]};return next;});}
  if(action==='add-series')return addSeries();
  if(action==='best-axes')return commit('Best readable axes',model=>{const next=normalizeChartModel(model);next.axes.x.labelInterval=Math.max(1,Math.ceil(next.dataset.rows.length/8));next.axes.x.rotation=next.dataset.rows.length>8?35:0;next.axes.y.zeroBaseline=next.chart_type.includes('Bar');next.axes.x.auto=true;next.axes.y.auto=true;return next;});
  if(action==='clean-labels')return commit('Clean labels',model=>{const next=normalizeChartModel(model);next.axes.x.labelInterval=Math.max(1,Math.ceil(next.dataset.rows.length/10));next.visual.dataLabels=next.dataset.rows.length<=14;return next;});
  if(action==='reset-selection')return resetTransientView();
  if(action==='add-reference'){const value=Number($('#cs-reference-value')?.value);return commit('Add reference line',model=>addReferenceLine(model,value,$('#cs-reference-label')?.value||'Reference'));}
  if(action==='add-band')return commit('Add reference band',model=>addReferenceBand(model,Number($('#cs-band-low')?.value),Number($('#cs-band-high')?.value),$('#cs-reference-label')?.value||'Reference band'));
  if(action==='add-annotation')return commit('Add annotation',model=>addAnnotation(model,{text:$('#cs-annotation-text')?.value,x:Number($('#cs-annotation-x')?.value)||.5,y:.25}));
}
root?.addEventListener('click',event=>{const clearSearch=event.target.closest('[data-human-field-search-clear]');if(clearSearch){state.fieldQuery='';renderPanel();requestAnimationFrame(()=> $('[data-human-field-search]')?.focus({preventScroll:true}));return;}const humanField=event.target.closest('[data-human-field]');if(humanField&&state.tab==='fields'){const role=state.activeRole||'value',field=fields().find(candidate=>candidate.id===humanField.dataset.humanField),assignment=humanMappingAssignment(state.model.mapping,role,field,fields(),chartHumanView());if(!assignment.ok){$('#cs-validation').textContent=assignment.error;return;}commit(`Map ${humanRoleLabel(role,{view:chartHumanView()})}`,model=>mapRole(model,role,field.id));return;}const removeField=event.target.closest('[data-multi-field-remove]');if(removeField){const select=$(`[data-multi-field="${removeField.dataset.multiFieldRemove}"]`);const option=[...select?.options||[]].find(candidate=>candidate.value===removeField.dataset.fieldId);if(option)option.selected=false;return renderPanel();}const edit=event.target.closest('[data-transform-edit]');if(edit){state.transformEditIndex=Number(edit.dataset.transformEdit);state.transformDraft=null;state.tab='data';render();return;}if(event.target.closest('[data-action="cancel-transform-edit"]')){state.transformEditIndex=null;state.transformDraft=null;return render();}const tab=event.target.closest('[data-cs-tab]');if(tab){state.tab=tab.dataset.csTab;$$('[data-cs-tab]').forEach(node=>{node.classList.toggle('is-active',node===tab);node.setAttribute('aria-selected',node===tab?'true':'false');});renderPanel();return;}const action=event.target.closest('[data-action]')?.dataset.action;if(action){event.preventDefault();handleAction(action);return;}const recommendation=event.target.closest('[data-recommendation]');if(recommendation){applyRecommendation(Number(recommendation.dataset.recommendation));return;}const recommendationPreview=event.target.closest('[data-recommendation-preview]');if(recommendationPreview){applyRecommendation(Number(recommendationPreview.dataset.recommendationPreview),true);return;}const recipeApply=event.target.closest('[data-recipe-apply]');if(recipeApply){const recipe=recipeAt(Number(recipeApply.dataset.recipeApply));if(recipe)commit('Apply chart recipe',model=>recipeToModel(model,recipe));return;}const recipeRename=event.target.closest('[data-recipe-rename]');if(recipeRename){const index=Number(recipeRename.dataset.recipeRename),recipe=recipeAt(index);if(recipe)openNameDialog('recipe',recipe.name||'Chart recipe',name=>{recipe.name=clean(name);persistRecipes(state.recipes);renderRecipes();});return;}const recipeDuplicate=event.target.closest('[data-recipe-duplicate]');if(recipeDuplicate){const recipe=recipeAt(Number(recipeDuplicate.dataset.recipeDuplicate));if(recipe){const copy={...clone(recipe),id:uid('recipe'),name:`${recipe.name} copy`};persistRecipes([copy,...state.recipes]);renderRecipes();}return;}const recipeDelete=event.target.closest('[data-recipe-delete]');if(recipeDelete){const id=recipeAt(Number(recipeDelete.dataset.recipeDelete))?.id;persistRecipes(state.recipes.filter(recipe=>recipe.id!==id));renderRecipes();return;}const up=event.target.closest('[data-transform-up]');if(up){editTransform(Number(up.dataset.transformUp),-1);return;}const down=event.target.closest('[data-transform-down]');if(down){editTransform(Number(down.dataset.transformDown),1);return;}const remove=event.target.closest('[data-transform-remove]');if(remove){removeTransform(Number(remove.dataset.transformRemove));return;}const seriesUp=event.target.closest('[data-series-up]');if(seriesUp){moveSeries(Number(seriesUp.dataset.seriesUp),-1);return;}const seriesDown=event.target.closest('[data-series-down]');if(seriesDown){moveSeries(Number(seriesDown.dataset.seriesDown),1);return;}const seriesHide=event.target.closest('[data-series-hide]');if(seriesHide){const index=Number(seriesHide.dataset.seriesHide);commit('Toggle series visibility',model=>{const next=normalizeChartModel(model);next.series[index].visible=next.series[index].visible===false;return next;});return;}const rename=event.target.closest('[data-column-rename]');if(rename){const index=Number(rename.dataset.columnRename),field=fields()[index];if(field)openNameDialog('column',field.name||'Field',name=>commit('Rename column',model=>renameColumn(model,index,name)));return;}const left=event.target.closest('[data-column-left]');if(left){const index=Number(left.dataset.columnLeft);return commit('Move column left',model=>reorderColumns(model,index,index-1));}const right=event.target.closest('[data-column-right]');if(right){const index=Number(right.dataset.columnRight);return commit('Move column right',model=>reorderColumns(model,index,index+1));}const rowHead=event.target.closest('[data-row]');if(rowHead){state.selectedRows=new Set([Number(rowHead.dataset.row)]);render();return;}const columnHead=event.target.closest('[data-column]');if(columnHead){state.selectedCols=new Set([Number(columnHead.dataset.column)]);render();return;}const cell=event.target.closest('[data-cell]');if(cell){const [row,col]=cell.dataset.cell.split(':').map(Number);selectCell(row,col,event.shiftKey);return;}handleChartClick(event);});
root?.addEventListener('change',event=>{const node=event.target;if(node.id==='cs-transform-kind'){updateTransformDraft(node,{typeChanged:true});return;}if(node.closest?.('.human-chart-transforms')){updateTransformDraft(node);return;}if(node.id==='cs-chart-type'){commit(`Switch to ${node.value}`,model=>switchChartType(model,node.value));return;}if(node.dataset.role){commit(`Map ${node.dataset.role}`,model=>mapRole(model,node.dataset.role,node.value));return;}if(node.dataset.seriesLabel||node.dataset.seriesColor||node.dataset.seriesAxis){const index=Number(node.dataset.seriesLabel??node.dataset.seriesColor??node.dataset.seriesAxis);commit('Edit series style',model=>{const next=normalizeChartModel(model);if(next.series[index]){if(node.dataset.seriesLabel)next.series[index].label=clean(node.value)||next.series[index].label;if(node.dataset.seriesColor)next.series[index].color=node.value;if(node.dataset.seriesAxis)next.series[index].axis=node.value;}return next;});return;}if(node.dataset.cell){const [row,col]=node.dataset.cell.split(':').map(Number);const value=node.value;state.cellDrafts.delete(node.dataset.cell);commit('Edit chart cell',model=>{const next=normalizeChartModel(model);if(next.dataset.rows[row]){const type=next.dataset.fields[col]?.type;next.dataset.rows[row][col]=type==='number'||type==='integer'?(value===''?null:(/^[-+]?\d+(\.\d+)?$/.test(value)?Number(value):value)):value;next.dataset.revision+=1;}return next;});return;}if(node.dataset.path)onPathChange(node);});
