function hideChartTooltip(){const tooltip=$('#cs-chart-tooltip');if(tooltip)tooltip.hidden=true;}
function showChartTooltip(target,event){if(!target||state.model.interaction?.tooltip===false)return hideChartTooltip();const tooltip=$('#cs-chart-tooltip');if(!tooltip)return;const text=target.dataset.tooltip||target.getAttribute('aria-label')||target.querySelector('title')?.textContent;if(!text)return;tooltip.textContent=text;tooltip.hidden=false;const margin=12,rect=tooltip.getBoundingClientRect(),x=Math.min(window.innerWidth-rect.width-8,Math.max(8,(event?.clientX??target.getBoundingClientRect().right)+margin)),y=Math.min(window.innerHeight-rect.height-8,Math.max(8,(event?.clientY??target.getBoundingClientRect().top)-rect.height-margin));tooltip.style.left=`${x}px`;tooltip.style.top=`${y}px`;}
function updateCrosshair(event){const svg=event.target.closest('svg.cs-chart-svg');if(!svg||state.model.interaction?.crosshair!==true)return;const layer=svg.querySelector('[data-crosshair-layer]'),plot=svg.querySelector('.cs-plot-area');if(!layer||!plot)return;const rect=plot.getBoundingClientRect(),x=Number(plot.getAttribute('x'))+Math.max(0,Math.min(1,(event.clientX-rect.left)/Math.max(1,rect.width)))*Number(plot.getAttribute('width'));layer.querySelector('line')?.setAttribute('x1',x.toFixed(2));layer.querySelector('line')?.setAttribute('x2',x.toFixed(2));layer.setAttribute('visibility','visible');}
function updateZoom(event){const svg=event.target.closest('svg.cs-chart-svg');if(!svg||state.model.interaction?.zoom!==true)return;const plan=interactionPlan(),factor=event.deltaY<0?.8:1.25,plot=svg.querySelector('.cs-plot-area');if(!plot)return;const rect=plot.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(event.clientX-rect.left)/Math.max(1,rect.width)));if(plan.xNumeric){const center=plan.xDomain.min+ratio*(plan.xDomain.max-plan.xDomain.min),span=(plan.xDomain.max-plan.xDomain.min)*factor;state.view.x={min:center-span*ratio,max:center+span*(1-ratio)};}const yRatio=Math.max(0,Math.min(1,(event.clientY-rect.top)/Math.max(1,rect.height))),yCenter=plan.yDomain.max-yRatio*(plan.yDomain.max-plan.yDomain.min),ySpan=(plan.yDomain.max-plan.yDomain.min)*factor;state.view.y={min:yCenter-ySpan*(1-yRatio),max:yCenter+ySpan*yRatio};render();}
function beginPointer(event){const svg=event.target.closest('svg.cs-chart-svg');if(!svg)return;if(event.shiftKey&&state.model.interaction?.pan===true){state.pointer={kind:'pan',x:event.clientX,y:event.clientY,view:clone(state.view)};return;}if(state.model.interaction?.brush===true&&!event.target.closest('[data-chart-point],[data-wafer-die]'))state.pointer={kind:'brush',x:event.clientX,y:event.clientY};}
function finishPointer(event){const pointer=state.pointer;state.pointer=null;if(!pointer||pointer.kind!=='brush')return;const left=Math.min(pointer.x,event.clientX),right=Math.max(pointer.x,event.clientX),top=Math.min(pointer.y,event.clientY),bottom=Math.max(pointer.y,event.clientY);const nodes=[...document.querySelectorAll('#cs-canvas [data-chart-point],[data-wafer-die]')].filter(node=>{const box=node.getBoundingClientRect(),cx=box.left+box.width/2,cy=box.top+box.height/2;return cx>=left&&cx<=right&&cy>=top&&cy<=bottom;});const selected=nodes.map(node=>Number(node.dataset.chartPoint??node.dataset.waferDie)).filter(Number.isInteger);state.selectedRows=new Set(selected);state.selectedCols=new Set(selectionColumnsForMarks(nodes));render();}
root?.addEventListener('wheel',event=>{if(event.target.closest('svg.cs-chart-svg')&&state.model.interaction?.zoom===true){event.preventDefault();updateZoom(event);}}, {passive:false});
