root?.addEventListener('focusin',event=>{const target=event.target.closest('[data-tooltip]');if(target)showChartTooltip(target,{clientX:target.getBoundingClientRect().right,clientY:target.getBoundingClientRect().top});});
root?.addEventListener('focusout',event=>{if(!event.relatedTarget?.closest?.('[data-tooltip]'))hideChartTooltip();});
root?.addEventListener('keydown',event=>{const interactive=event.target.closest?.('[data-legend-series],[data-chart-point],[data-wafer-die]');if(interactive&&(event.key==='Enter'||event.key===' '||event.key==='Spacebar')){event.preventDefault();const identity={legend:interactive.dataset.legendSeries,point:interactive.dataset.chartPoint,wafer:interactive.dataset.waferDie,series:interactive.dataset.seriesKey};handleChartClick({target:interactive});requestAnimationFrame(()=>{const target=[...root.querySelectorAll('[data-legend-series],[data-chart-point],[data-wafer-die]')].find(node=>(identity.legend&&node.dataset.legendSeries===identity.legend)||(identity.point!==undefined&&node.dataset.chartPoint===identity.point&&node.dataset.seriesKey===identity.series)||(identity.wafer!==undefined&&node.dataset.waferDie===identity.wafer));target?.focus();});return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='c'&&event.target.closest('[data-cell]')){event.preventDefault();copyRange();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='v'&&event.target.closest('[data-cell]')){event.preventDefault();pasteRange();return;}});
$('#cs-import-json')?.addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{const value=JSON.parse(await file.text()),model=value.chart||value.chart_studio||value;commit('Import chart setup',()=>normalizeChartModel(model,state.model.chart_type));}catch(error){$('#cs-save-status').textContent=`Import rejected: ${error.message}`;}event.target.value='';});
$('#cs-name-dialog')?.addEventListener('close',event=>{const request=state.nameDialog;state.nameDialog=null;if(event.target.returnValue==='confirm'&&request){const value=clean($('#cs-name-input')?.value);if(value)request.onConfirm(value);}});
$('#cs-name-dialog form')?.addEventListener('submit',event=>{event.preventDefault();const request=state.nameDialog;state.nameDialog=null;const value=clean($('#cs-name-input')?.value);event.currentTarget.closest('dialog')?.close('confirm');if(value&&request)request.onConfirm(value);});
window.CompanyUIChartStudio={get state(){return {...state,selectedRows:[...state.selectedRows],selectedCols:[...state.selectedCols],undo:state.undo.length,redo:state.redo.length};},get model(){return state.model;},hash:()=>hash(state.model),layoutHash:()=>hash({type:state.model.chart_type,mapping:state.model.mapping,axes:state.model.axes,rows:state.model.dataset.rows}),command(name,payload={}){if(name==='paste')commit('Paste data',model=>updateChartData(model,payload.text||''));if(name==='switch')commit('Switch chart',model=>switchChartType(model,payload.type));if(name==='set'){commit(`Set ${payload.path}`,model=>{const next=normalizeChartModel(model);setPath(next,payload.path,payload.value);return next;});}if(name==='save')saveReport();return state.model;},receive(message){if(message?.type==='report.commit_result'){state.pending=null;state.revision=Number(message.payload?.revision||state.revision);state.dirty=false;$('#cs-save-status').textContent=`Saved · revision ${state.revision}`;}else if(message?.type==='report.error'){state.pending=null;$('#cs-save-status').textContent=`Save error: ${message.payload?.message||'unknown error'}`;}}};
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.preview){state.preview=false;render();}});
render();
